 let savedItems=readJSON(STORAGE.saved,[]),tripIds=readJSON(STORAGE.trip,[]),activeCategory="all",onlySaved=false,roomCapacity="all",currentModalLocation=null,galleryIndex=0;
 function readJSON(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}function storeJSON(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}function numberFormat(v){if(v===null||v===undefined||!Number.isFinite(Number(v)))return "—";return new Intl.NumberFormat(englishMode?"en-US":"fa-IR",{maximumFractionDigits:0}).format(Number(v))}function mapsLink(l){return MAP_SEARCH+encodeURIComponent(l.maps)}
 function renderRooms(){const host=$("#roomsGrid");if(!host)return;const data=rooms.filter(r=>roomCapacity==="all"||r.capacity===Number(roomCapacity));host.innerHTML=data.map((r,i)=>`<article class="room-card ${r.style}"><div class="room-photo"><img src="${r.img}" alt="تصویر مفهومی ${safe(r.title)}" loading="lazy"><span class="room-label">${safe(r.badge)} · تصویر مفهومی</span><button class="room-favorite ${savedItems.includes(r.id)?"saved":""}" data-room-save="${r.id}" type="button" aria-label="ذخیره‌ی ${safe(r.title)}">${icons("i-heart")}</button></div><div class="room-content"><div class="room-title-row"><h3>${safe(r.title)}</h3><span class="room-number">V / ${fa(i+1)}</span></div><p>${safe(r.desc)}</p><div class="room-tags"><span class="room-tag">${icons("i-users")} ظرفیت ${fa(r.capacity)} نفر</span><span class="room-tag">${icons("i-pin")} شیراز</span></div><div class="room-amenities">${r.features.map(x=>`<span>${icons("i-check")}${safe(x)}</span>`).join("")}</div><div class="room-actions"><a class="btn btn-gold" href="${r.link}" target="_blank" rel="noopener">رزرو در جاجیگا ${icons("i-arrow")}</a><a class="room-photo-more" href="${r.link}" target="_blank" rel="noopener" aria-label="جزئیات ${safe(r.title)}">${icons("i-arrow")}</a></div></div></article>`).join("");translatePage(host);$$("[data-room-save]",host).forEach(btn=>btn.addEventListener("click",()=>{const id=btn.dataset.roomSave;savedItems=savedItems.includes(id)?savedItems.filter(x=>x!==id):[...savedItems,id];storeJSON(STORAGE.saved,savedItems);renderRooms();renderLocations();toast(savedItems.includes(id)?"واحد به علاقه‌مندی‌ها اضافه شد.":"واحد حذف شد.")}));updateSavedCount()}
 function getFilteredLocations(){const query=($('#locationSearch')?.value||'').trim().toLocaleLowerCase(englishMode?'en':'fa');return locations.filter(l=>{const cat=activeCategory==='all'||l.category===activeCategory;const saved=!onlySaved||savedItems.includes(l.id);const terms=[l.name,l.en,l.categoryName,...l.tags,l.desc,englishText(l.name),englishText(l.categoryName),...l.tags.map(englishText),englishText(l.desc),englishText(l.tip)].join(' ').toLocaleLowerCase(englishMode?'en':'fa');return cat&&saved&&(!query||terms.includes(query))})}
 function renderLocations(){const host=$('#locationGrid');if(!host)return;const data=getFilteredLocations();host.innerHTML=data.map(l=>`<article class="spot-card ${l.theme}" data-location-card="${l.id}" tabindex="0" aria-label="کارت ${safe(l.name)}"><div class="spot-art"><img src="${l.image}" alt="تصویر هنری الهام‌گرفته از ${safe(l.name)}" loading="lazy"><div class="spot-topline"><span class="spot-kind"><i></i>${safe(l.categoryName)}</span><span class="spot-no">${l.n} / SHIRAZ</span></div><span class="art-chip">تصویر هنری</span><span class="spot-emblem">${icons(l.icon)}</span><div class="spot-art-caption"><small>${safe(l.en)}</small><strong>${safe(l.name)}</strong></div></div><div class="spot-info"><p class="spot-summary">${safe(l.desc)}</p><div class="spot-meta"><span class="spot-distance">${icons("i-pin")}${safe(l.distance)}</span><div class="spot-tags">${l.tags.slice(0,2).map(t=>`<span class="spot-tag">${safe(t)}</span>`).join("")}</div></div><div class="spot-actions"><button class="spot-action primary-action" data-location-details="${l.id}" type="button">${icons("i-info")} جزئیات</button><a class="spot-action" href="${mapsLink(l)}" target="_blank" rel="noopener">${icons("i-map")} مسیر</a><button class="spot-action icon-only ${savedItems.includes(l.id)?"saved":""}" data-location-save="${l.id}" type="button" aria-label="علاقه‌مندی ${safe(l.name)}" title="ذخیره در علاقه‌مندی‌ها">${icons("i-heart")}</button></div></div></article>`).join("");translatePage(host);$('#emptyLocations')?.classList.toggle('hidden',data.length>0);host.classList.toggle('hidden',data.length===0);bindLocationCards(host);renderMapTags();updateSavedCount()}
 function bindLocationCards(host){$$("[data-location-details]",host).forEach(b=>b.addEventListener("click",()=>openLocationModal(b.dataset.locationDetails)));$$("[data-location-save]",host).forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.locationSave;savedItems=savedItems.includes(id)?savedItems.filter(x=>x!==id):[...savedItems,id];storeJSON(STORAGE.saved,savedItems);renderLocations();renderRooms();toast(savedItems.includes(id)?"به علاقه‌مندی‌ها اضافه شد.":"از علاقه‌مندی‌ها حذف شد.")}));$$(".spot-card",host).forEach(card=>{card.addEventListener("pointermove",e=>{if(e.pointerType!=="mouse"||matchMedia("(prefers-reduced-motion: reduce)").matches)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;card.style.setProperty("--mx",`${(x*100).toFixed(1)}%`);card.style.setProperty("--my",`${(y*100).toFixed(1)}%`);card.style.transform=`perspective(1050px) rotateX(${((.5-y)*3.2).toFixed(2)}deg) rotateY(${((x-.5)*3.2).toFixed(2)}deg) translateY(-4px)`});card.addEventListener("pointerleave",()=>{card.style.transform="";card.style.setProperty("--mx","50%");card.style.setProperty("--my","30%")});card.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target===card){e.preventDefault();openLocationModal(card.dataset.locationCard)}})})}
 let locationMapInstance=null,mapStayMarker=null,mapPlaceMarkers=new Map(),activeMapPopupId=null,locationView='cards';
 function getPlaceDistance(l){const rad=x=>x*Math.PI/180;const R=6371000,dp=rad(l.lat-STAY_POINT.lat),dl=rad(l.lon-STAY_POINT.lon),a=Math.sin(dp/2)**2+Math.cos(rad(STAY_POINT.lat))*Math.cos(rad(l.lat))*Math.sin(dl/2)**2;return Math.round(2*R*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)))}
 function prettyDistance(m){if(m<1000)return (englishMode?'~':'حدود ')+numberFormat(m)+(englishMode?' m':' متر');const km=(m/1000).toFixed(m>=10000?0:1);return (englishMode?'~':'حدود ')+(englishMode?km:km.replace('.',','))+(englishMode?' km':' کیلومتر')}
 function renderMapTags(){const host=$('#mapLocationTags');if(!host)return;const visible=getFilteredLocations(),visibleIds=new Set(visible.map(l=>l.id));if(locationMapInstance){locations.forEach(l=>{const marker=mapPlaceMarkers.get(l.id);if(!marker)return;if(visibleIds.has(l.id)){if(!locationMapInstance.hasLayer(marker))marker.addTo(locationMapInstance)}else if(locationMapInstance.hasLayer(marker))locationMapInstance.removeLayer(marker)})}host.innerHTML=visible.map(l=>`<button class="map-place-tag" type="button" data-map-location="${l.id}"><span class="map-place-dot ${l.category}"></span><span class="map-place-name">${safe(l.name)}</span><small>${prettyDistance(getPlaceDistance(l))}</small><span class="map-place-open">↗</span></button>`).join('');host.querySelectorAll('[data-map-location]').forEach(btn=>btn.addEventListener('click',()=>{const loc=locations.find(x=>x.id===btn.dataset.mapLocation);if(!loc)return;if(locationMapInstance&&mapPlaceMarkers.has(loc.id)){locationMapInstance.setView([loc.lat,loc.lon],15,{animate:true});mapPlaceMarkers.get(loc.id).openPopup()}else{openLocationModal(loc.id)}}));translatePage(host)}
 function initLocationMap(){const mapEl=$('#locationMap');if(!mapEl||locationMapInstance)return;if(!window.L){mapEl.innerHTML=`<div class="map-fallback"><strong>${englishMode?'Interactive map could not load':'نقشه تعاملی بارگذاری نشد'}</strong><p>${englishMode?'Check your connection, or use the property map link below.':'اتصال اینترنت را بررسی کن یا لینک پین اقامتگاه را باز کن.'}</p><a class="btn btn-gold btn-small" href="https://maps.app.goo.gl/aM4ZekBX2bC79dep7" target="_blank" rel="noopener">${englishMode?'Open property in Google Maps':'باز کردن موقعیت اقامتگاه'}</a></div>`;return}try{locationMapInstance=L.map(mapEl,{scrollWheelZoom:false,zoomControl:true}).setView([STAY_POINT.lat,STAY_POINT.lon],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(locationMapInstance);const stayIcon=L.divIcon({className:'stay-map-pin-wrap',html:`<div class="stay-map-pin"><span>⌂</span><b>VakilStay</b></div>`,iconSize:[116,38],iconAnchor:[58,19]});mapStayMarker=L.marker([STAY_POINT.lat,STAY_POINT.lon],{icon:stayIcon,zIndexOffset:1000}).addTo(locationMapInstance).bindPopup(`<strong>${englishMode?'VakilStay accommodation':'اقامتگاه وکیل'}</strong><br><small>${englishMode?'Approximate central location':'نقطه‌ی مرکزی تقریبی'}</small><br><a href="https://maps.app.goo.gl/aM4ZekBX2bC79dep7" target="_blank" rel="noopener">${englishMode?'Open exact property pin ↗':'باز کردن پین اصلی ↗'}</a>`);locations.forEach(l=>{const icon=L.divIcon({className:'place-map-pin-wrap',html:`<div class="place-map-pin ${l.category}"><span>${l.n}</span></div>`,iconSize:[32,38],iconAnchor:[16,35]});const marker=L.marker([l.lat,l.lon],{icon}).addTo(locationMapInstance).bindPopup(`<div class="map-popup"><strong>${safe(englishMode?englishText(l.name):l.name)}</strong><small>${safe(englishMode?englishText(l.categoryName):l.categoryName)} · ${prettyDistance(getPlaceDistance(l))}</small><a href="${mapsLink(l)}" target="_blank" rel="noopener">${englishMode?'Open directions ↗':'باز کردن مسیر ↗'}</a><button type="button" data-map-detail="${l.id}">${englishMode?'View place details':'مشاهده جزئیات'}</button></div>`);marker.on('click',()=>{activeMapPopupId=l.id});marker.on('popupopen',e=>{const btn=e.popup.getElement()?.querySelector('[data-map-detail]');btn?.addEventListener('click',()=>openLocationModal(l.id),{once:true})});mapPlaceMarkers.set(l.id,marker)});setTimeout(()=>locationMapInstance?.invalidateSize(),150)}catch(e){mapEl.innerHTML=`<div class="map-fallback">${englishMode?'Map could not be initialized.':'نقشه آماده نشد.'}</div>`}}
 function setLocationView(view){locationView=view;const cards=$('#locationGrid'),panel=$('#locationMapPanel');if(cards)cards.classList.toggle('hidden',view!=='cards');if(panel)panel.classList.toggle('hidden',view!=='map');$$('#locationViewTabs [data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active))});if(view==='map'){initLocationMap();renderMapTags();setTimeout(()=>locationMapInstance?.invalidateSize(),120)}}
