 function setupReveal(){const nodes=$$(".reveal");if(!("IntersectionObserver"in window)){nodes.forEach(x=>x.classList.add("visible"));return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");io.unobserve(e.target)}}),{threshold:.1});nodes.forEach(x=>io.observe(x))}
