 async function shareSite(){const url="https://bita-prsp.github.io/Vakilstay/";try{if(navigator.share)await navigator.share({title:"VakilStay | Stay & Explore Shiraz",text:"Find accommodation, attractions, weather and travel tips for Shiraz, Iran.",url});else{await navigator.clipboard.writeText(url);toast("لینک سایت کپی شد.")}}catch{toast("اشتراک‌گذاری لغو شد.")}}function setupShare(){$("#shareSite")?.addEventListener("click",shareSite);$("#footerShare")?.addEventListener("click",shareSite)}
