 async function loadInsights(){const status=$("#insightsStatus"),refresh=$("#refreshInsights");if(!status)return;status.classList.remove("ok","error");status.querySelector("span").textContent="در حال دریافت آمار واقعی...";refresh?.classList.add("spinning");try{const response=await fetch("https://github-page-insights-worker.game-developer-mb.workers.dev/v1/platforms/vakilstay?days=30&lite=1",{headers:{Accept:"application/json"},cache:"no-store"});if(!response.ok)throw Error("HTTP "+response.status);const raw=await response.json(),data=raw.data&&typeof raw.data==="object"?raw.data:raw,totals=data.totals||data.stats||data.summary||data;const views=firstNumber(totals.views,totals.pageviews,totals.pageViews,totals.totalViews,data.views,data.pageviews);if(views===null)throw Error("No view totals");$("#metricViews").textContent=numberFormat(views);status.classList.add("ok");status.querySelector("span").textContent="آمار به‌روز است"}catch(e){status.classList.add("error");status.querySelector("span").textContent="آمار فعلاً در دسترس نیست";$("#metricViews").textContent="—"}finally{refresh?.classList.remove("spinning")}}
 function firstNumber(...values){for(const v of values){if(v!==null&&v!==undefined&&v!==""&&Number.isFinite(Number(v)))return Number(v)}return null}async function loadLifetime(){const el=$("#metricLifetime");if(!el)return;try{const r=await fetch("https://github-page-insights-worker.game-developer-mb.workers.dev/v1/platforms/vakilstay?lite=1",{headers:{Accept:"application/json"},cache:"no-store"});if(!r.ok)throw Error("unavailable");const raw=await r.json(),d=raw.data&&typeof raw.data==="object"?raw.data:raw,t=d.totals||d.stats||d.summary||d;const n=firstNumber(t.views,t.pageviews,t.pageViews,t.totalViews,t.lifetimeViews,d.views,d.pageviews,d.totalViews);if(n===null)throw Error("missing totals");el.textContent=numberFormat(n)}catch{el.textContent="—"}}function setupInsights(){const run=()=>{loadInsights();loadLifetime()};$("#refreshInsights")?.addEventListener("click",run);$("#retryInsights")?.addEventListener("click",run);setTimeout(run,2500)}
 function setupFallbacks(){document.addEventListener("error",e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||img.dataset.fallbackUsed==="1")return;const fb=img.dataset.fallback;if(fb){img.dataset.fallbackUsed="1";img.src=fb}},true);$$("img").forEach(img=>{if(img.complete&&img.naturalWidth===0&&img.dataset.fallback){img.dataset.fallbackUsed="1";img.src=img.dataset.fallback}})}
