 const WEATHER_EN={"آفتابی":"Sunny","نیمه‌ابری":"Partly cloudy","ابری":"Cloudy","مه‌آلود":"Foggy","بارانی":"Rain","برفی":"Snow","رعدوبرق":"Thunderstorms","وضعیت هوا":"Weather conditions"};
 function weatherLabel(code){if(code===0)return {label:"آفتابی",icon:"☀️"};if([1,2].includes(code))return {label:"نیمه‌ابری",icon:"🌤️"};if(code===3)return {label:"ابری",icon:"☁️"};if([45,48].includes(code))return {label:"مه‌آلود",icon:"🌫️"};if([51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return {label:"بارانی",icon:"🌦️"};if([71,73,75,77,85,86].includes(code))return {label:"برفی",icon:"❄️"};if([95,96,99].includes(code))return {label:"رعدوبرق",icon:"⛈️"};return {label:"وضعیت هوا",icon:"🌡️"}}
 function localizedWeatherLabel(code){const x=weatherLabel(code);return englishMode?(WEATHER_EN[x.label]||x.label):x.label}
 let calendarToday=null,holidayData=null,clockTimer=null;
 function updateShirazClock(){const now=new Date();const clock=$('#shirazClock');if(clock)clock.textContent=new Intl.DateTimeFormat(englishMode?'en-GB':'fa-IR',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(now);const date=$('#shirazDate');if(date){if(calendarToday?.sh){const sh=calendarToday.sh;const weekday=englishMode?(sh.weekday_en||''):(sh.weekday_fa||'');const month=englishMode?(sh.month_name_en||''):(sh.month_name_fa||'');const shText=`${weekday} · ${fa(sh.day)} ${month} ${fa(sh.year)}`;const greg=new Intl.DateTimeFormat(englishMode?'en-US':'fa-IR',{timeZone:'Asia/Tehran',year:'numeric',month:'short',day:'numeric'}).format(now);date.textContent=englishMode?`${shText} · ${greg}`:shText+' · '+greg;}else{date.textContent=new Intl.DateTimeFormat(englishMode?'en-u-ca-persian':'fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(now)}}}
 const SH_MONTHS_FA=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];const SH_MONTHS_EN=['Farvardin','Ordibehesht','Khordad','Tir','Mordad','Shahrivar','Mehr','Aban','Azar','Dey','Bahman','Esfand'];function solarMonthName(month,en){return (en?SH_MONTHS_EN:SH_MONTHS_FA)[Number(month)-1]||String(month)}
 async function loadCalendar(){const date=$('#shirazDate'),holiday=$('#holidayNote');try{const r=await fetch('https://www.persian-calendar.com/api/today?tz=Asia%2FTehran',{cache:'no-store'});if(!r.ok)throw Error('calendar API');calendarToday=await r.json();updateShirazClock();const sh=calendarToday.sh;if(sh?.year&&sh?.month){if(!holidayData||holidayData.year!==sh.year){const hr=await fetch(`https://www.persian-calendar.com/api/holidays?year=${sh.year}`,{cache:'force-cache'});if(hr.ok){const h=await hr.json();holidayData={year:sh.year,data:Array.isArray(h.data)?h.data:[]}}}const allDays=holidayData?.data||[],todayIndex=allDays.findIndex(x=>Number(x.month_sh)===Number(sh.month)&&Number(x.day_sh)===Number(sh.day)),today=allDays[todayIndex],events=(today?.events||[]).filter(e=>e.is_holiday);if(holiday){holiday.classList.toggle('is-holiday',events.length>0);if(events.length){holiday.textContent=(englishMode?'Public holiday: ':'تعطیل رسمی: ')+(englishMode?(events[0].title_en||events[0].title_fa):(events[0].title_fa||events[0].title_en))}else{const next=allDays.find(x=>(Number(x.month_sh)>Number(sh.month)||(Number(x.month_sh)===Number(sh.month)&&Number(x.day_sh)>Number(sh.day)))&&(x.events||[]).some(e=>e.is_holiday));const event=next?.events?.find(e=>e.is_holiday);const nextDate=next?(englishMode?`${next.day_sh} ${solarMonthName(next.month_sh,true)} ${next.year_sh||sh.year}`:`${fa(next.day_sh)} ${solarMonthName(next.month_sh,false)} ${fa(next.year_sh||sh.year)}`):'';holiday.textContent=next&&event?(englishMode?'Next public holiday: ':'تعطیلی بعدی: ')+(englishMode?(event.title_en||event.title_fa):(event.title_fa||event.title_en))+` · ${nextDate}`:(englishMode?'No public holiday listed today':'امروز تعطیل رسمی ثبت نشده است')}}}}catch(e){if(date&&!calendarToday)date.textContent=new Intl.DateTimeFormat(englishMode?'en-u-ca-persian':'fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(new Date());if(holiday)holiday.textContent=englishMode?'Holiday information is temporarily unavailable':'اطلاعات تعطیلات فعلاً در دسترس نیست'}updateShirazClock()}
 async function loadWeather(){const grid=$('#forecastGrid'),current=$('#weatherCurrent');if(!grid)return;grid.innerHTML=`<div class="forecast-loading">${englishMode?'Loading the forecast…':'در حال دریافت پیش‌بینی آب‌وهوا…'}</div>`;const btn=$('#refreshWeather');if(btn)btn.disabled=true;try{const url='https://api.open-meteo.com/v1/forecast?latitude=29.6157&longitude=52.5444&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m,precipitation,cloud_cover&timezone=Asia%2FTehran&forecast_days=7';const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw Error('weather unavailable');const d=await res.json(),c=d.current||{},daily=d.daily||{},now=weatherLabel(c.weather_code);$('#weatherTemp').textContent=Math.round(c.temperature_2m??0)+'°C';$('#weatherIcon').textContent=now.icon;$('#weatherSummary').textContent=localizedWeatherLabel(c.weather_code)+(c.cloud_cover!=null?` · ${Math.round(c.cloud_cover)}% ${englishMode?'cloud cover':'پوشش ابر'}`:'');$('#weatherFeels').textContent=(englishMode?'Feels like ':'حس‌شده ')+Math.round(c.apparent_temperature??c.temperature_2m??0)+'°';$('#weatherHumidity').textContent=Math.round(c.relative_humidity_2m??0)+'%';$('#weatherWind').textContent=Math.round(c.wind_speed_10m??0)+(englishMode?' km/h':' کیلومتر/ساعت');$('#weatherRain').textContent=Math.round(daily.precipitation_probability_max?.[0]??0)+'%';const dates=daily.time||[];grid.innerHTML=dates.map((date,i)=>{const w=weatherLabel(daily.weather_code?.[i]);const day=new Date(date+'T12:00:00').toLocaleDateString(englishMode?'en-US':'fa-IR',{weekday:'short',month:'short',day:'numeric',timeZone:'Asia/Tehran'});const max=Math.round(daily.temperature_2m_max?.[i]??0),min=Math.round(daily.temperature_2m_min?.[i]??0),rain=Math.round(daily.precipitation_probability_max?.[i]??0);return `<article class="forecast-card" title="${englishMode?'High':'بیشینه'} ${max}° · ${englishMode?'Low':'کمینه'} ${min}°"><span class="forecast-day">${safe(day)}</span><span class="forecast-icon" aria-hidden="true">${w.icon}</span><strong class="forecast-condition">${safe(localizedWeatherLabel(daily.weather_code?.[i]))}</strong><div class="forecast-temperatures"><b>${max}°</b><span>${min}°</span></div><div class="forecast-detail"><span>☂ ${rain}%</span></div></article>`}).join('');$('#weatherUpdated').textContent=(englishMode?'Updated ':'به‌روزرسانی ')+new Date().toLocaleTimeString(englishMode?'en-GB':'fa-IR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tehran'});translatePage()}catch(e){grid.innerHTML=`<div class="forecast-loading forecast-error">${englishMode?'Weather is unavailable right now. Check your connection and try again.':'پیش‌بینی هوا فعلاً در دسترس نیست. اتصال اینترنت را بررسی کنید و دوباره تلاش کنید.'}</div>`;$('#weatherSummary').textContent=englishMode?'Data temporarily unavailable':'اطلاعات فعلاً در دسترس نیست'}finally{if(btn)btn.disabled=false}}
