 function englishText(raw){const trimmed=String(raw).trim();if(!trimmed)return raw;const translated=EN_FIXES[trimmed]??EN_TEXT[trimmed]??EN_DATA[trimmed];if(translated!==undefined)return String(raw).replace(trimmed,translated);let out=String(raw);for(const [fa,en] of EN_PARTS)out=out.replaceAll(fa,en);return out.replace(/[۰-۹]/g,d=>"۰۱۲۳۴۵۶۷۸۹".indexOf(d))}
 function translatePage(root=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(n){return n.parentElement&&!['SCRIPT','STYLE','NOSCRIPT'].includes(n.parentElement.tagName)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});let n;while((n=walker.nextNode())){if(!Object.prototype.hasOwnProperty.call(n,'__faOriginal'))n.__faOriginal=n.nodeValue;const original=n.__faOriginal;n.nodeValue=englishMode?englishText(original):original}const attrs=['placeholder','title','aria-label','alt'];root.querySelectorAll?.('*').forEach(el=>{if(!el.__faAttrs)el.__faAttrs={};for(const attr of attrs){if(!el.hasAttribute(attr))continue;if(!(attr in el.__faAttrs))el.__faAttrs[attr]=el.getAttribute(attr);el.setAttribute(attr,englishMode?englishText(el.__faAttrs[attr]):el.__faAttrs[attr])}})}
 function setupLanguage(){const b=$('#languageToggle');if(!b)return;const saved=localStorage.getItem('vakilstay:language');englishMode=saved==='en';let languageInitialized=false;function apply(){document.documentElement.lang=englishMode?'en':'fa';document.documentElement.dir=englishMode?'ltr':'rtl';document.body.classList.toggle('english-mode',englishMode);b.textContent=englishMode?'FA':'EN';b.setAttribute('aria-label',englishMode?'Switch to Persian':'Switch to English');localStorage.setItem('vakilstay:language',englishMode?'en':'fa');translatePage();renderRooms();renderLocations();renderTripModal();updateSavedCount();if(languageInitialized)loadWeather();updateShirazClock();renderMapTags();if(locationMapInstance){locationMapInstance.remove();locationMapInstance=null;mapStayMarker=null;mapPlaceMarkers.clear();if(locationView==='map')setTimeout(initLocationMap,40)}languageInitialized=true}b.addEventListener('click',()=>{englishMode=!englishMode;apply()});const observer=new MutationObserver(records=>{if(!englishMode)return;let should=false;for(const rec of records){if(rec.type==='childList'&&rec.addedNodes.length)should=true;if(rec.type==='characterData'&&rec.target&&!Object.prototype.hasOwnProperty.call(rec.target,'__faOriginal'))should=true}if(should)queueMicrotask(()=>translatePage())});observer.observe(document.body,{subtree:true,childList:true,characterData:true});apply()}
 let deferredInstall=null;function setupInstall(){const n=$("#installNudge"),install=$("#installApp");if(!n)return;window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredInstall=e;n.hidden=false});install?.addEventListener("click",async()=>{if(!deferredInstall){toast("از منوی مرورگر گزینه Add to Home Screen را انتخاب کنید.");return}deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;n.hidden=true});$("#dismissInstall")?.addEventListener("click",()=>n.hidden=true);window.addEventListener("appinstalled",()=>{n.hidden=true;toast("VakilStay به دستگاه اضافه شد.")})}
 function hideLoader(){const l=$("#siteLoader");if(!l)return;setTimeout(()=>{l.classList.add("loader-hidden");setTimeout(()=>l.remove(),650)},Math.min(1200,Math.max(350,performance.now()<800?800:0)))}
 function init(){hideLoader();setupWeather();setupLanguage();setupInstall();applyTheme();setupHeader();setupReveal();setupActiveNav();setupRooms();renderRooms();setupLocationFilters();renderLocations();setupLocationViewTabs();setupTrip();renderTripModal();setupModals();setupGallery();setupShare();setupInsights();setupSearchKeys();setupFallbacks();updateSavedCount();$('#year').textContent=new Date().getFullYear();translatePage();if(locationView==='map')initLocationMap()}
 init();window.VakilStay={locations,rooms,renderLocations,openTripModal,loadInsights};
